import Root from "./2Managing State/3PreserrvingandResetting"
import What from "./1Adding Interactivity/Fundamental"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"
import {useState} from "react"

export default function () {
  const [show,setShow] = useState(false)
  return (
    <>
    <Input show={show} set={setShow}/>
    {show ? <div><Counter/></div> : <Counter/>}
    </>
  );
}

function Input({show, set}) {
  return <input style={{display: "block"}} type="checkbox" checked={show} onChange={(e) => {set(e.target.checked)}}/>
}

function Counter() {
  const [count, setCount] = useState(0)
  return <>
  <button onClick={() => {setCount(count+1)}}>click</button><br/>
  {count} <br/>
  </>
}

